#include <stdio.h>
#include <stdlib.h>

int compare_chars(const void *a, const void *b) {
    return *(const char *)a - *(const char *)b;
}

int main(void) {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    char password[505];
    scanf("%s", password);

    char options[505][30];
    for (int i = 0; i < M; i++) {
        scanf("%s", options[i]);
        qsort(options[i], K, sizeof(char), compare_chars);
    }

    long long P;
    scanf("%lld", &P);

    long long suffix[505];
    suffix[M] = 1;
    for (int i = M - 1; i >= 0; i--) {
        suffix[i] = suffix[i + 1] * K;
        if (suffix[i] > P) suffix[i] = P;
    }

    long long rank = P - 1;
    int index = 0;

    for (int i = 0; i < N; i++) {
        if (password[i] == '#') {
            long long digit = rank / suffix[index + 1];
            rank %= suffix[index + 1];
            password[i] = options[index][digit];
            index++;
        }
    }

    printf("%s\n", password);
    return 0;
}
